# 1.7 — мировая классика, вторая пачка
R = []
HEADS = 'Головы и панцири креветок'

def shrimp_add(grams, how='Креветки — в конце, на 2 минуты до розового.'):
    """Добавка «+ креветки»: покупаем целые, головы уходят на склад."""
    return dict(name='+ креветки (целые — головы на склад)', yields=[HEADS],
                ing=[['Креветки целые (с головой)', grams * 2, 'г', {'note': f'≈{grams} г мяса; очищенные тоже ок — тогда {grams} г'}]],
                note='Почистить (как — в варианте «Целые креветки» у жареного риса), головы и панцири — в пакет в морозилку, после «Приготовлено» они будут на складе. ' + how)

